// Order-24 IIR, TRANSPOSED feedforward chain: one multiply+add per stage
// (registered partial sums) + a tiny feedback stage -> critical path roughly
// independent of the order -> high Fmax. Same function as the reference, confirm
// the TRANSPOSED chain.
module iir24_v2 (
  input clk, input rst_n, input [7:0] x, output reg [15:0] y
);
  reg [15:0] r1;
  reg [15:0] r2;
  reg [15:0] r3;
  reg [15:0] r4;
  reg [15:0] r5;
  reg [15:0] r6;
  reg [15:0] r7;
  reg [15:0] r8;
  reg [15:0] r9;
  reg [15:0] r10;
  reg [15:0] r11;
  reg [15:0] r12;
  reg [15:0] r13;
  reg [15:0] r14;
  reg [15:0] r15;
  reg [15:0] r16;
  reg [15:0] r17;
  reg [15:0] r18;
  reg [15:0] r19;
  reg [15:0] r20;
  reg [15:0] r21;
  reg [15:0] r22;
  reg [15:0] r23;
  reg [15:0] r24;
  reg [15:0] y2;
  always @(posedge clk) begin
    if (!rst_n) begin y <= 16'd0; y2 <= 16'd0; r1 <= 16'd0; r2 <= 16'd0; r3 <= 16'd0; r4 <= 16'd0; r5 <= 16'd0; r6 <= 16'd0; r7 <= 16'd0; r8 <= 16'd0; r9 <= 16'd0; r10 <= 16'd0; r11 <= 16'd0; r12 <= 16'd0; r13 <= 16'd0; r14 <= 16'd0; r15 <= 16'd0; r16 <= 16'd0; r17 <= 16'd0; r18 <= 16'd0; r19 <= 16'd0; r20 <= 16'd0; r21 <= 16'd0; r22 <= 16'd0; r23 <= 16'd0; r24 <= 16'd0; end
    else begin
      y <= (63*x + r1 + ((9*y)>>4) + ((5*y2)>>4)) & 16'hFFFF;
      y2 <= (15*x + r2) & 16'hFFFF;
      r1 <= (4*x + r3) & 16'hFFFF;
      r2 <= (35*x + r4) & 16'hFFFF;
      r3 <= (41*x + r5) & 16'hFFFF;
      r4 <= (47*x + r6) & 16'hFFFF;
      r5 <= (40*x + r7) & 16'hFFFF;
      r6 <= (2*x + r8) & 16'hFFFF;
      r7 <= (60*x + r9) & 16'hFFFF;
      r8 <= (19*x + r10) & 16'hFFFF;
      r9 <= (5*x + r11) & 16'hFFFF;
      r10 <= (12*x + r12) & 16'hFFFF;
      r11 <= (50*x + r13) & 16'hFFFF;
      r12 <= (28*x + r14) & 16'hFFFF;
      r13 <= (46*x + r15) & 16'hFFFF;
      r14 <= (49*x + r16) & 16'hFFFF;
      r15 <= (15*x + r17) & 16'hFFFF;
      r16 <= (22*x + r18) & 16'hFFFF;
      r17 <= (36*x + r19) & 16'hFFFF;
      r18 <= (52*x + r20) & 16'hFFFF;
      r19 <= (8*x + r21) & 16'hFFFF;
      r20 <= (31*x + r22) & 16'hFFFF;
      r21 <= (50*x + r23) & 16'hFFFF;
      r22 <= (57*x + r24) & 16'hFFFF;
      r23 <= (45*x) & 16'hFFFF;
      r24 <= (0*x) & 16'hFFFF;
    end
  end
endmodule lfsr(
    input clk,
    input reset,
    output reg [6:0] q
);
    reg [6:0] r;
    always @(posedge clk) begin
        if(reset) begin
            r <= 7'b1000000;
            q <= 7'b1000000;
        end else begin
            r[0] <= r[6] ^ r[5];
            r[1] <= r[0] ^ r[6];
            r[2] <= r[1] ^ r[0];
            r[3] <= r[2] ^ r[1];
            r[4] <= r[3] ^ r[2];
            r[5] <= r[4] ^ r[3];
            r[6] <= r[5] ^ r[4];
            q <= r;
        end
    end
end
